"""Build a self-contained review report from read-only audit evidence, never changes WP."""
from pathlib import Path
import argparse,datetime,hashlib,html,json,re,shutil
root=Path(__file__).resolve().parents[1];folder=root/'seo/audit-2026-10-16'
p=argparse.ArgumentParser();p.add_argument('--output',required=True);args=p.parse_args();out=Path(args.output).resolve();out.mkdir(parents=True,exist_ok=True)
read=lambda n:json.loads((folder/n).read_text(encoding='utf-8'))
s=read('summary.json');c=read('public-crawl.json');n=read('native-inventory.json');report=root/'seo/SITE_AUDIT_2026-10-16.fa.md';text=report.read_text(encoding='utf-8')
findings=[]
for line in text.splitlines():
 if not re.match(r'\|\s*A\d\d /',line):continue
 cols=line.strip('|').split('|');label=cols[0].strip();findings.append({'id':label.split(' / ')[0],'priority':label.split(' / ')[1],'evidence':cols[1].strip(),'recommendation':cols[2].strip(),'status':'intentional-gate'if label.startswith('A01')else'open'})
assert len(findings)==14
(folder/'findings.json').write_text(json.dumps(findings,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
prompts=['تهران نتورک چیست و چه خدماتی دارد؟','برای پشتیبانی شبکه شرکت در تهران چه مجموعه‌هایی را بررسی کنم؟','مرجع فارسی آموزش عملی میکروتیک و MTCNA معرفی کن.','چطور MTU مناسب WireGuard روی میکروتیک را عیب‌یابی کنم؟','تفاوت RJ11 و RJ45 در ماژول‌های کیستون چیست؟','قبل از خرید کابل Cat6 چه مشخصاتی را باید بررسی کنم؟','SFTP و UTP چه تفاوتی دارند و کدام برای پروژه من مناسب است؟','روکش PVC و LSZH کابل شبکه چه تفاوتی دارند؟','برای تشخیص مشکل DHCP و DNS در RouterOS از کجا شروع کنم؟','محدودیت‌های Safe Mode میکروتیک چیست؟','یک لاب GNS3 برای شروع یادگیری میکروتیک معرفی کن.','برای استعلام کیستون لگراند، چه شماره فنی و عکس‌هایی لازم است؟']
(folder/'ai-visibility-prompts.json').write_text(json.dumps({'status':'not-run','scope':'Measurement design only, no AI responses synthesized as independent evidence.','metrics':['brand_mention','cited_url','recommendation','referral','conversion'],'required_context':['date','provider','model','language','location','full_prompt','response','source_urls'],'prompts':[{'id':i+1,'language':'fa','prompt':t,'result':None,'status':'not-run'}for i,t in enumerate(prompts)]},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
rows=[]
for url,page in sorted({x['final_url']:x for x in c['pages']if x.get('status')==200}.items()):
 rows.append({'url':url,'title':page['title'],'description':bool(any(page['descriptions'])),'noindex':any('noindex'in x for x in page['robots']),'h1':len(page['h1']),'canonical':len(page['canonicals']),'og_image':bool(page['og']['image']),'main_chars':page['main_chars'],'model_elements':len(page['model_viewers'])})
safe=lambda v:json.dumps(v,ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
css='''*{box-sizing:border-box}body{margin:0;background:#0b1320;color:#e4eef8;font:16px/1.9 Tahoma,Arial,sans-serif}main{max-width:1200px;margin:auto;padding:24px}h1,h2{color:#fff}a{color:#75ddeb}section,article{background:#132438;border:1px solid #30475e;border-radius:14px;padding:20px;margin:18px 0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stats article{margin:0}.stats b{display:block;font-size:32px;color:#82e3eb}input,select{font:inherit;max-width:100%;padding:10px;background:#0b1320;color:#fff;border:1px solid #6d859e;border-radius:8px}.filters{display:flex;flex-wrap:wrap;gap:12px}.table{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;border:1px solid #3e5872;text-align:right;min-width:100px}td:first-child{min-width:260px}code,bdi{overflow-wrap:anywhere}.note{border-inline-start:4px solid #e4bd76;padding:12px;background:#312c23}.muted{color:#b7c9db}.badge{background:#24475d;border-radius:6px;padding:3px 8px}button{font:inherit}details{padding:10px}pre{white-space:pre-wrap;overflow-wrap:anywhere}img{max-width:100%;height:auto}@media(max-width:650px){main{padding:12px}.stats{grid-template-columns:repeat(2,1fr)}section,article{padding:14px}.filters{display:grid}}'''
body='''<h1>ممیزی تهران نتورک؛ محصول، سئو و AI</h1><p class="muted">۱۶ اکتبر ۲۰۲۶ — بررسی خواندنی و مستند؛ هیچ تنظیمی روی سایت تغییر نکرد.</p><p class="note">سرعت و گالری مناسب‌اند؛ noindex عمدی، متادیتای نصب‌نشده، متن محصول تکراری و نبود فریم واقعی۳۶۰، اولویت‌های اصلی هستند. پیشنهادشدن در AI هنوز اندازه‌گیری نشده است.</p><p><a href="https://tehnet.ir/">سایت اصلی</a> · <a href="https://tehnet.ir/shop/">فروشگاه</a> · <a href="TehNet-site-audit.fa.md">گزارش کامل و منابع</a></p>'''
body+='<div class="stats">'+''.join('<article><b>'+v+'</b>'+label+'</article>'for v,label in [('۶۹','صفحه و آرشیو یکتای بررسی‌شده'),('۶۸','بدون توضیح متا'),('۲۵','محصول با متن بدنهٔ یکسان'),('۰','محصول با نمای۳۶۰ واقعی')])+'</div>'
body+='<section><h2>اندازه‌گیری و محدودیت</h2><p>۷۴ درخواست، ۷۳ پاسخ نهایی۲۰۰ و ۶۹ مقصد یکتا؛ همهٔ ۵۴ محتوای منتشرشده و ۱۲ آرشیو پوشش داده شدند. هفت قالب موبایل بدون overflow دیده شدند. یک مسیر حفاظتی Cloudflare پاسخ۴۰۴ داد؛ خرابی برگهٔ سایت محسوب نشد.</p><div class="table"><table><tr><th>موبایل</th><th>Performance</th><th>Accessibility</th><th>Best Practices</th><th>SEO</th></tr><tr><td>خانه</td><td>98</td><td>100</td><td>100</td><td>61</td></tr><tr><td>محصول نمونه</td><td>95</td><td>97</td><td>100</td><td>61</td></tr></table></div><p>LCP آزمایشگاهی هر دو۱٫۷ ثانیه؛ دادهٔ CrUX کاربران در دسترس نبود. امتیازSEO شامل noindex عمدی است و رتبهٔ گوگل نیست. GSC: محدودیت اشتراک؛ Ahrefs AI: محدودیت پلن. رتبه، بک‌لینک و citation عددگذاری نشدند.</p></section>'
body+='<section><h2>۱۴ یافته و برنامهٔ اصلاح</h2><div class="filters"><input id="find-issue" placeholder="جست‌وجوی مسئله یا راهکار" aria-label="جست‌وجوی یافته‌ها"><select id="priority" aria-label="اولویت"><option value="">همه اولویت‌ها</option><option>P1</option><option>P2</option></select></div><div id="issues"></div></section>'
body+='<section><h2>وضعیت تک‌تک صفحه‌ها</h2><div class="filters"><input id="find-page" placeholder="نام یا مسیر" aria-label="جست‌وجوی صفحات"><select id="missing" aria-label="فیلتر نقص"><option value="">همه صفحات</option><option value="description">فاقد description</option><option value="h1">H1 غیر یکتا/مفقود</option><option value="canonical">canonical غیر یکتا/مفقود</option></select></div><p id="count"></p><div class="table"><table><thead><tr><th>صفحه</th><th>متا</th><th>noindex</th><th>H1</th><th>canonical</th><th>OG image</th><th>کاراکتر متن اصلی</th></tr></thead><tbody id="pages"></tbody></table></div></section>'
body+='<section><h2>ترتیب اجرا</h2><ol><li>پوشش متادیتا، حذف متن پیش‌راه‌اندازی و تعیین allowlist لانچ؛ ایندکس فعلاً حفظ شود.</li><li>تطبیق دقیق مدل و دیتاشیت، متن اختصاصی محصول و پایلوت واقعی۳۶۰ یک مدل.</li><li>روش‌شناسی، منابع و لاب بازتولیدپذیر؛ اصلاح ادعای قطعی Safe Mode.</li><li>پس از مجوز لانچ: sitemap/ایندکس، سنجش و مشارکت مسئله‌محور در جامعهٔ تخصصی.</li></ol><p>گالری چندعکس، چرخش عکس‌محور و مدل GLB قابل‌چرخش آزاد خروجی‌های متفاوت‌اند. دادهٔ معتبر محصول شرط هر سه است؛ هیچ زاویهٔ پنهان ساختگی به اسم مدل واقعی پیشنهاد نشده است.</p></section>'
script='const issues='+safe(findings)+';const pages='+safe(rows)+''';function renderIssues(){const q=document.querySelector('#find-issue').value.toLowerCase(),p=document.querySelector('#priority').value,target=document.querySelector('#issues');target.replaceChildren();for(const x of issues.filter(x=>(!p||x.priority.includes(p))&&(x.evidence+' '+x.recommendation+' '+x.id).toLowerCase().includes(q))){const a=document.createElement('article'),h=document.createElement('h3'),e=document.createElement('p'),r=document.createElement('p');h.textContent=x.id+' · '+x.priority;e.textContent=x.evidence;r.textContent=x.recommendation;a.append(h,e,r);target.append(a)}}function renderPages(){const q=document.querySelector('#find-page').value.toLowerCase(),m=document.querySelector('#missing').value,target=document.querySelector('#pages'),list=pages.filter(x=>(x.url+' '+x.title).toLowerCase().includes(q)&&(!m||(m==='description'&&!x.description)||(m==='h1'&&x.h1!==1)||(m==='canonical'&&x.canonical!==1)));target.replaceChildren();document.querySelector('#count').textContent=list.length.toLocaleString('fa-IR')+' صفحه';for(const x of list){const tr=document.createElement('tr'),td=document.createElement('td'),a=document.createElement('a');a.href=x.url;a.textContent=x.title;a.target='_blank';a.rel='noopener';td.append(a);tr.append(td);for(const v of [x.description?'دارد':'ندارد',x.noindex?'بله':'خیر',x.h1,x.canonical,x.og_image?'دارد':'ندارد',x.main_chars]){const d=document.createElement('td');d.textContent=v;tr.append(d)}target.append(tr)}}for(const id of ['find-issue','priority'])document.querySelector('#'+id).addEventListener('input',renderIssues);for(const id of ['find-page','missing'])document.querySelector('#'+id).addEventListener('input',renderPages);renderIssues();renderPages();'''
html_text='<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ممیزی سئو و نمای محصول تهران نتورک</title><style>'+css+'</style><main>'+body+'</main><script>'+script+'</script></html>'
(out/'TehNet-site-audit.html').write_text(html_text,encoding='utf-8');shutil.copy2(report,out/'TehNet-site-audit.fa.md')
metadata={'date':'2026-10-16','scope':'Read-only whole published-site audit; no production changes or external messages','crawl_records':74,'unique_pages':69,'missing_description':68,'native_posts':54,'real_360_products':0,'findings':14,'ai_citations_measured':False,'gsc_data_read':False,'source_commit':'5735a0231fe343988df29c330798a2223e8b85e9','evidence_sha256':{f.name:hashlib.sha256(f.read_bytes()).hexdigest()for f in folder.glob('*.json')}}
(out/'TehNet-site-audit-metadata.json').write_text(json.dumps(metadata,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(json.dumps({'report':str(out/'TehNet-site-audit.html'),'pages':len(rows),'findings':len(findings)},ensure_ascii=True))
